const $=id=>document.getElementById(id);let current=null,lastQuery='',controller=null,serial=0;
function validIP(s){if(/^\d{1,3}(\.\d{1,3}){3}$/.test(s))return s.split('.').every(n=>Number(n)<=255&&(n==='0'||!n.startsWith('0')));if(!s.includes(':')||/[^0-9a-f:.]/i.test(s))return false;try{return new URL('http://['+s+']/').hostname.startsWith('[')}catch{return false}}
function status(message,error=false){$('status').textContent=message;$('status').className=error?'error':''}
function reset(){current=null;['ip','org','asn','timezone','city','country','postal','updated'].forEach(id=>$(id).textContent='—');$('place').textContent='Informasi koneksi akan muncul di sini';$('region').textContent='Lokasi belum tersedia';$('coords').textContent='Koordinat belum tersedia';$('map').hidden=true;$('copy').disabled=$('download').disabled=true;$('version').textContent='MENUNGGU'}
async function lookup(query=''){query=query.trim();if(query&&!validIP(query)){status('Format IP tidak valid. Gunakan IPv4 seperti 8.8.8.8 atau IPv6 seperti 2606:4700:4700::1111.',true);return}controller?.abort();controller=new AbortController();const signal=controller.signal;const request=++serial;lastQuery=query;reset();$('result-title').textContent=query?'HASIL PENCARIAN IP':'IP PUBLIK ANDA';$('state').textContent='Memeriksa…';$('results').setAttribute('aria-busy','true');$('search').disabled=true;status('Memeriksa IP dan informasi jaringan…');const timeout=setTimeout(()=>controller?.signal===signal&&controller.abort(),12000);try{const response=await fetch(`https://ipwho.is/${query?encodeURIComponent(query):''}`,{signal,cache:'no-store'});if(!response.ok)throw new Error(response.status===429?'Batas layanan data tercapai. Silakan coba lagi nanti.':'Layanan data belum dapat merespons. Coba lagi.');const raw=await response.json();const d={...raw,error:raw.success===false,version:raw.type,org:raw.connection?.isp||raw.connection?.org,asn:raw.connection?.asn?`AS${raw.connection.asn}`:null,timezone:raw.timezone?.id,country_name:raw.country};if(request!==serial)return;if(d.error)throw new Error(d.reserved?'IP privat atau reserved tidak memiliki informasi lokasi publik.':'Data IP tidak tersedia. Pastikan alamat merupakan IP publik.');if(!d.ip||!validIP(d.ip))throw new Error('Respons penyedia data tidak valid.');current=d;const fields={ip:d.ip,org:d.org,asn:d.asn,timezone:d.timezone,city:d.city,country:d.country_name,postal:d.postal,region:[d.region,d.country_name].filter(Boolean).join(', '),place:[d.city,d.country_name].filter(Boolean).join(', '),version:d.version|| (d.ip.includes(':')?'IPv6':'IPv4'),updated:new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})};Object.entries(fields).forEach(([id,value])=>$(id).textContent=value||'Tidak tersedia');if(Number.isFinite(d.latitude)&&Number.isFinite(d.longitude)){$('coords').textContent=`${d.latitude.toFixed(4)}, ${d.longitude.toFixed(4)}`;$('map').href=`https://www.openstreetmap.org/?mlat=${d.latitude}&mlon=${d.longitude}#map=10/${d.latitude}/${d.longitude}`;$('map').hidden=false}$('copy').disabled=$('download').disabled=false;$('state').textContent='Pemeriksaan selesai';status('Data dari ipwho.is · Lokasi bersifat perkiraan.')}catch(e){if(request!==serial)return;status(e.name==='AbortError'?'Koneksi terlalu lama. Periksa koneksi Anda dan coba lagi.':e instanceof TypeError?'Tidak dapat menghubungi penyedia data. Periksa koneksi atau coba lagi nanti.':e.message,true);$('state').textContent='Data tidak tersedia';$('version').textContent='BELUM TERSEDIA'}finally{clearTimeout(timeout);if(request===serial){$('results').setAttribute('aria-busy','false');$('search').disabled=false}}}
$('form').addEventListener('submit',e=>{e.preventDefault();lookup($('query').value)});document.querySelectorAll('[data-ip]').forEach(b=>b.addEventListener('click',()=>{$('query').value=b.dataset.ip;lookup(b.dataset.ip)}));$('mine').onclick=()=>{$('query').value='';lookup()};$('refresh').onclick=()=>lookup(lastQuery);$('copy').onclick=async()=>{if(!current)return;try{await navigator.clipboard.writeText(current.ip);status('Alamat IP berhasil disalin.')}catch{status('Tidak dapat menyalin otomatis. Pilih dan salin alamat IP secara manual.',true)}};$('download').onclick=()=>{if(!current)return;const url=URL.createObjectURL(new Blob([JSON.stringify(current,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='ip-lens-'+current.ip.replace(/:/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};lookup();
